	 var u = src.match(/url: '(.*m3u8)'/)[1]
	 var pi="✅播放ing";
	 java.log(pi)
	 var b64 = java.base64Encode(
`<html>
    <head>
        <meta name="viewport" content="width=device-width">
        <style>
            body {
                margin: 0;
